float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=1;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_buff1;
float4 amzSample_buff1(float2 uv) { return float4(amzt_buff1.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_buff1(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_SSS;
uniform float amzp_SSSS;
uniform float amzp_PROGRESS;
uniform float amzp_SPEED;
uniform float amzp_lineWidth;
uniform float amzp_lineCountX;
uniform float amzp_lineCountY;
uniform float amzp_SHIGH;
layout(color) uniform half4 amzp_gridColor;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
    float4 newLayer( float4 a, float4 b) { return a * (1. - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float progT() { return (amzp_autop>0.5) ? amzp_PROGRESS + (time*amzp_SPEED) : amzp_PROGRESS; }
    float noise(float2 p) {
        float3 p3 = fract(float3(p.xyx) * .1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    float getHeight(float2 uv, float amzLocal_time) {
        uv += .5;
        uv.y -= amzLocal_time*6.;
        float2 i = floor(uv), f = fract(uv);
        float a = noise(i), b = noise(i + float2(1., 0.)), c = noise(i + float2(0., 1.)), d = noise(i + float2(1., 1.));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }
    float getDistance(float3 p, float amzLocal_time) {
        return p.z-(1.-cos(p.x*15.))*.03*getHeight(float2(p.x*amzp_lineCountX, p.y*amzp_lineCountY/3.), amzLocal_time);
    }
    float getGridColor(float2 uv, float amzLocal_time){
        float3 cam = float3(0., 1., .1);
        float3 fwd = normalize(-cam);
        float3 u = normalize(cross(fwd, float3(1.,0.,0.)));
        float3 r = cross(u, fwd);
        float3 ray = normalize(fwd + r*uv.x + u*uv.y);
        float col = 0.;
        float distOrigin = 0.;
        bool hit = false;
        float3 p = cam;
        for(int i=0; i<160; i++){
            float d = getDistance(p, amzLocal_time);
            if(d < .001 + distOrigin*.0015) { hit = true; break; }
            if(distOrigin > 2.) break;
            float s = max(d*.75, .0005);
            p += ray*s;
            distOrigin += s;
        }
        if(!hit) return 0.;
        float lineW = max(amzp_lineWidth*distOrigin, .0001);
        float xLines = smoothstep(lineW, 0., abs(fract(p.x*amzp_lineCountX)-.5));
        float yLines = smoothstep(lineW*2., 0., abs(fract(p.y*(amzp_lineCountY/3.)-amzLocal_time*6.)-.5));
        col = max(xLines, yLines);
        return max(0., col-(distOrigin*.8));
    }
