        float xLines = smoothstep(lineW, 0., abs(fract(p.x*amzp_lineCountX)-.5));
        float yLines = smoothstep(lineW*2., 0., abs(fract(p.y*(amzp_lineCountY/3.)-amzLocal_time*6.)-.5));
        col = max(xLines, yLines);
        return max(0., col-(distOrigin*.8));
    }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        if (amzPass == 0) { amzOutput = texColor; return; }
        float amzLocal_time = progT();
        float2 satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y *= layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((180.0+amzp_angle)*0.0174533);
        satriyaid += float2((-250.0+amzp_position.x), (170.0+amzp_position.y))*float2(-1.,1.)/500.;
        satriyaid /= float2(amzp_scale*amzp_stretch.x, amzp_scale*amzp_stretch.y);
        float sunHeight = amzp_SHIGH;
        float2 uv = satriyaid;
        uv.y -= sunHeight;
        float dist = 2.5*length(uv-float2(0.5,0.5));
        float divisions = 50.0;
        float pattern = (sin(uv.y*divisions*10. - amzLocal_time*2.)*1.2+uv.y*8.3)*uv.y-1.5+
            sin(uv.x*20.+amzLocal_time*5.)*.01;
        float sunOutline = smoothstep( 0.0,-0.0315, max( dist - 0.315, -pattern));
        float3 c = float3(0.0);
        if((amzp_SSS>0.5)) c += sunOutline * mix(float3( 4.0, 0.0, 0.2), float3(1.0, 1.1, 0.0), uv.y);
        float glow = max(0.0, 1.0 - dist * 1.25);
        glow = min(glow * glow * glow, 0.325);
        if((amzp_SSSS>0.5)) c += glow * float3(1.5, 0.3, 1.2) * 1.1;
        uv -= .5;
        uv.y += sunHeight;
        uv.y += .18;
        if(uv.y < 0.1) c += getGridColor(uv, amzLocal_time)*4.*amzp_gridColor.rgb*amzp_gridColor.a;
        float flick = 1.3+sin(amzLocal_time*30. +uv.y*1400.)*.1;
        float scanline = smoothstep(1.-.2/1400.,1.,sin(amzLocal_time*30.*.1+uv.y*4.));
        float3 rgb = max(c * flick * (scanline*.2+1.), float3(0.));
        float4 resultfinal;
        float3 base = texColor.a > 0.0001 ? texColor.rgb/texColor.a : float3(0.);
        if( int(amzp_blendMode)==0 ) {
            resultfinal = float4(min(rgb*amzp_hardness, float3(1.)), 1.0) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            float3 f = min(rgb*amzp_hardness, float3(1.));
            resultfinal = float4(base*f, 1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            float3 f = min(rgb*amzp_hardness, float3(1.));
            resultfinal = float4(1.-(1.-base)*(1.-f), 1.0) * texColor.a;
        } else {
            float3 f = min(rgb*amzp_hardness, float3(1.));
            float fa = clamp(max(f.r, max(f.g, f.b)), 0., 1.);
            resultfinal = newLayer(float4(base, 1.0), float4(f, fa)) * texColor.a;
        }
        amzOutput = mix(texColor, resultfinal, amzp_alpha);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
